<script setup lang="ts">
import { computed } from 'vue'
import { RouterLink } from 'vue-router'
import StatusBadge from '@/components/StatusBadge.vue'
import SourceHealth from '@/components/SourceHealth.vue'
import { useDashboardStore } from '@/stores/dashboard'
import { formatInstant } from '@/domain/dashboard'
import type { WikiCandidateSummary, WikiFormalDocumentSummary, WikiReferenceSummary } from '@/domain/dashboard'

const store = useDashboardStore()
const snapshot = computed(() => store.snapshot)
const documents = computed(() => snapshot.value?.wikiDocuments ?? [])
const candidates = computed(() => snapshot.value?.wikiCandidates ?? [])

function qualificationLabel(reference: WikiReferenceSummary): string {
  return {
    approved: '资格已确认', pending: '资格待确认', rejected: '资格已拒绝', revoked: '资格已撤回', unknown: '资格未知',
  }[reference.qualification]
}
function candidateStateLabel(candidate: WikiCandidateSummary): string {
  return { candidate: '候选草稿', review_pending: '候选待审核', approved_pending_formalization: '已批准，等待正式化', rejected: '候选已拒绝', revoked: '候选已撤回', formalized: '已正式化' }[candidate.state]
}
function referenceClass(reference: WikiReferenceSummary): string {
  return `reference--${reference.qualification}`
}
function timeLabel(value: string): string {
  return formatInstant(value, 'short')
}
</script>

<template>
  <div v-if="snapshot" class="page-stack">
    <header class="page-header"><div><p class="eyebrow">知识与治理 · LLM-WIKI</p><h1>知识与候选</h1><p>把正式内容、候选变化和精确资源资格放在同一条可核对的观察线上。</p></div><span class="read-only-mark"><span aria-hidden="true">◉</span> 只读观察</span></header>
    <div v-if="snapshot.sources.find((source) => source.id === 'wiki')?.status !== 'fresh'" class="notice-banner" role="status"><span aria-hidden="true">◷</span><div><strong>Wiki 来源包含非最新数据</strong><p>正式内容与候选状态按各自观测时间显示；资格未知时不会被推断为通过。</p></div><RouterLink to="/operations">查看来源 <span aria-hidden="true">↗</span></RouterLink></div>
    <section class="knowledge-summary"><div><span>正式文档</span><strong>{{ documents.length.toString().padStart(2, '0') }}</strong><small>当前已激活版本</small></div><div><span>候选变化</span><strong>{{ candidates.length.toString().padStart(2, '0') }}</strong><small>隔离于正式内容之外</small></div><div><span>待确认引用</span><strong>{{ candidates.reduce((total, item) => total + item.references.filter((reference) => reference.qualification !== 'approved').length, 0).toString().padStart(2, '0') }}</strong><small>需要精确版本资格事实</small></div><p>候选内容可以被观察，但不会被显示成正式版本。</p></section>
    <div class="knowledge-grid">
      <section class="panel formal-panel"><header class="section-heading"><div><p class="eyebrow">FORMAL CONTENT</p><h2>已发布正式版本</h2></div><span class="panel-meta">SQLite 指针 + 精确 Commit</span></header><article v-for="document in documents" :key="document.id" class="formal-card"><div class="formal-card__heading"><div><h3>{{ document.title }}</h3><p>{{ document.summary }}</p></div><span class="formal-stamp">FORMAL</span></div><div class="formal-card__meta"><span>FormalRevision · {{ document.formalRevisionId }}</span><time :datetime="document.updatedAt">更新于 {{ timeLabel(document.updatedAt) }}</time></div><div class="references"><span class="references__label">精确资源引用</span><div v-for="reference in document.references" :key="reference.id" class="reference" :class="referenceClass(reference)"><div><strong>ResourceVersion · {{ reference.resourceVersionId }}</strong><small>使用范围：{{ reference.requestedScope }}</small></div><span>{{ qualificationLabel(reference) }}</span></div></div></article><p v-if="!documents.length" class="quiet-empty">当前没有已激活的正式 Wiki 文档。</p></section>
      <section class="panel candidate-panel"><header class="section-heading"><div><p class="eyebrow">CANDIDATE GOVERNANCE</p><h2>候选变化</h2></div><span class="panel-meta">不进入正式内容</span></header><article v-for="candidate in candidates" :key="candidate.id" class="candidate-card"><div class="candidate-card__heading"><div><span class="candidate-card__proposal">Proposal · {{ candidate.proposalId }}</span><h3>{{ candidate.title }}</h3></div><StatusBadge :status="candidate.state" :label="candidateStateLabel(candidate)" /></div><p class="candidate-card__notice">{{ candidate.candidateSnapshotStatus === 'unavailable' ? '候选快照暂时无法确认；仅显示治理身份，不展示其内容或引用资格。' : candidate.state === 'review_pending' ? '候选待审核，引用资格仍需按精确 ResourceVersion 核验。' : candidate.state === 'approved_pending_formalization' ? 'Project Owner 已批准此候选，正式查询仍保持旧版本直到正式化成功。' : '候选状态由治理记录提供。' }}</p><div class="references"><div v-for="reference in candidate.references" :key="reference.id" class="reference" :class="referenceClass(reference)"><div><strong>ResourceVersion · {{ reference.resourceVersionId }}</strong><small>使用范围：{{ reference.requestedScope }}</small></div><span>{{ qualificationLabel(reference) }}</span></div></div><footer><time :datetime="candidate.updatedAt">最近变化 {{ timeLabel(candidate.updatedAt) }}</time><span>隔离候选 · 不显示为正式版本</span></footer></article><p v-if="!candidates.length" class="quiet-empty">当前没有待观察的候选变化。</p></section>
    </div>
    <section class="panel knowledge-rules"><header class="section-heading"><div><p class="eyebrow">读法说明</p><h2>如何理解这些状态</h2></div></header><div class="rules-grid"><article><span class="rule-index">01</span><strong>正式版本</strong><p>只有当前正式指针、成功正式化结果和精确内容快照全部一致时，才会展示为正式内容。</p></article><article><span class="rule-index">02</span><strong>候选变化</strong><p>候选永远保持隔离状态；待审核、拒绝或撤回的内容不会被当作当前 Wiki。</p></article><article><span class="rule-index">03</span><strong>资源资格</strong><p>资格绑定精确 ResourceVersion 和使用范围。没有确认记录时显示待确认，不替换成“最新资源”。</p></article></div></section>
    <footer class="page-footnote"><span>看板只展示观察到的事实，不会提交、审核或发布 Wiki。</span><span>来源状态 · <RouterLink to="/operations">查看运行观察 ↗</RouterLink></span></footer>
  </div>
</template>

